          label="服役日期"
          fieldProps={{ format: 'YYYY-MM-DD' }}
        />
        <ProFormDigit
          name="life_span"
          label="可用年限(月)"
          min={0}
          fieldProps={{ precision: 0 }}
        />
        <ProFormSelect
          name="status"
          label="状态"
          options={[
            { label: '启用', value: 1 },
            { label: '停用', value: 0 },
          ]}
          rules={[{ required: true, message: '请选择状态' }]}
        />
        <ProFormText
          name="desc"
          label="描述"
          rules={[
            { max: 128, message: '描述最多128个字符' },
          ]}
        />
      </ModalForm>
    </PageContainer>
  );
};

export default DeviceListPage;

